import sys

def main():
    code = sys.stdin.read().strip()

    if len(code) != 10:
        print("Invalid promotional code.")
        return

    has_digit = False
    has_upper = False

    for char in code:
        if char.isdigit():
            has_digit = True
        if char.isupper():
            has_upper = True

    if has_digit and has_upper:
        print("Valid promotional code.")
    else:
        print("Invalid promotional code.")

if __name__ == "__main__":
    main()
